SELECT MAX(borysiuk_rating) AS max_borysiuk, MAX(puel_rating) AS max_puel
FROM (
    SELECT borysiuk_rating FROM (
        SELECT overall_rating AS borysiuk_rating FROM Player_Attributes WHERE player_api_id IN (SELECT player_api_id FROM Player WHERE player_name = 'Ariel Borysiuk')
    )
    UNION ALL
    SELECT puel_rating FROM (
        SELECT overall_rating AS puel_rating FROM Player_Attributes WHERE player_api_id IN (SELECT player_api_id FROM Player WHERE player_name = 'Paulin Puel')
    )
);

SELECT 
